class TestCartesianProduct(unittest.TestCase):
    """TDD cycle 1: expand a plain matrix into its cross product."""

    def test_two_axis_product(self):
        matrix = {
            "os": ["ubuntu-latest", "macos-latest"],
            "python": ["3.11", "3.12"],
        }
        combos = expand_matrix(matrix)
        self.assertEqual(
            combos,
